cards.solution:
import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] skor = {72, 88, 65, 91, 80};
        Arrays.sort(skor);
        System.out.println(Arrays.toString(skor));
        System.out.println(skor[0]);
        System.out.println(skor[skor.length - 1]);
    }
}

